const I18N={
  skip:'.notr,.tst-q1,textarea,input,.nm,.pname,#tbproj,.tst-grid td,pre,.relnotes,.th-art,.folder-demo code,.tst-cols,.tst-tn,.cs-what,.aitem span,.in-q b,.qe',
  tr(s){if(!s)return s;const m=s.match(/^(\s*)([\s\S]*?)(\s*)$/),core=m[2];if(!core)return s;
    if(Object.prototype.hasOwnProperty.call(EN,core))return m[1]+EN[core]+m[3];
    for(const [rx,rep] of EN_RX){if(rx.test(core))return m[1]+core.replace(rx,rep)+m[3];}
    return s;},
  node(n){
    if(n.nodeType===3){const p=n.parentElement;if(!p||p.closest(this.skip))return;if(p.closest('svg')&&!p.closest('.emp'))return;
      const v=n.nodeValue,t=this.tr(v);if(t!==v)n.nodeValue=t;return;}
    if(n.nodeType!==1)return;
    if(n.matches&&n.matches(this.skip))return;
    for(const a of ['title','placeholder','aria-label']){const v=n.getAttribute&&n.getAttribute(a);if(v){const t=this.tr(v);if(t!==v)n.setAttribute(a,t);}}
    if(n.matches&&n.matches('.emp')){const t=this.tr(n.textContent);if(t!==n.textContent)n.textContent=t;return;}
    if(n.tagName==='svg'||n.closest&&n.closest('svg')){n.querySelectorAll&&n.querySelectorAll('.emp').forEach(e=>{const t=this.tr(e.textContent);if(t!==e.textContent)e.textContent=t;});return;}
    for(const c of n.childNodes)this.node(c);
  },
  start(){
    if(LANG()!=='en')return;
    document.documentElement.lang='en';
    this.node(document.body);document.title=this.tr(document.title);
    new MutationObserver(ms=>{for(const m of ms){
      if(m.type==='characterData')this.node(m.target);
      else if(m.type==='attributes')this.node(m.target);
      else m.addedNodes.forEach(x=>this.node(x));}}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['title','placeholder','aria-label']});
    new MutationObserver(()=>{const t=this.tr(document.title);if(t!==document.title)document.title=t;}).observe(document.querySelector('title'),{childList:true,characterData:true,subtree:true});
  }
};
// Para textos que no pasan por la pantalla (SQL generado, nombres nuevos…)
function t(s){return LANG()==='en'?I18N.tr(s):s;}
